preferences.citekeyFormat:
type(Case) + shorttitle(4, 4).nopunct + Court.nopunct.prefix("_") + year;
type(Statute) + CodeNumber.nopunct + Code.nopunct.select(n = 4) + Section.nopunct;
type(Standard) + Organization.len("!=", 1).nopunct.skipwords.select(n = 4).postfix(_) + Genre.nopunct.skipwords.select(n = 5) + Number.prefix(_);
type(NewspaperArticle) + auth.len.nopunct + shorttitle(3, 3).len.nopunct.prefix("_") + PublicationTitle.select(n = 4).prefix("_") + year.default(_nd);
type(Document) + auth.len.nopunct + shorttitle(3, 3).len.nopunct.prefix("_") + year.default(_nd);
type(WebPage) + auth.len.nopunct + WebsiteTitle.nopunct.select(n = 4).prefix("_") + year.default(_nd);
type(BlogPost) + auth.len.nopunct + BlogTitle.nopunct.select(n = 4).prefix("_") + year.default(_nd);
(auth || shorttitle) + year.default(_nd)

